args.command:
node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [
  [-1, false], [0, true], [3, true], [4, false],
  ['3', false], [null, false], [NaN, false], [1.5, false],
  [undefined, false], [Infinity, false], [-Infinity, false],
];
for (const [value, expected] of cases) {
  const actual = permit(value);
  if (actual !== expected) {
    console.log(`FAIL ${String(value)} expected ${expected} got ${actual}`);
    process.exitCode = 1;
  } else {
    console.log(`PASS ${String(value)} -> ${actual}`);
  }
}
EOF
